//! Exact mounted-volume proof using only a new own synthetic project directory.
use imagine_server::{
    private_storage::Root,
    storage::Store,
    video::{contract::*, persistence::*},
};
use std::path::Path;

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    let root = Root::system().map_err(anyhow::Error::msg)?;
    let project = VideoProject::create(serde_json::from_str(include_str!(
        "../design/video-contract/create-project.json"
    ))?)
    .map_err(|error| anyhow::anyhow!(error.code))?;
    let id = project.id.clone();
    // The ID is freshly generated by the source-owned fixture. Nothing is
    // enumerated or reopened in another project or the private library.
    let layout = root.project(&id.0).map_err(anyhow::Error::msg)?;
    let runtime = imagine_server::storage_layout::runtime_directory(
        std::env::var_os("XDG_RUNTIME_DIR")
            .as_deref()
            .map(Path::new),
    )
    .map_err(anyhow::Error::msg)?
    .join(format!("storage-test-{}", uuid::Uuid::new_v4().simple()));
    std::fs::create_dir_all(&runtime)?;
    let root = root
        .with_runtime_directory(runtime.clone())
        .map_err(anyhow::Error::msg)?;
    let mut session = ProjectSession::new(project)?;
    session.save_private(&root)?;
    let reopened = ProjectSession::open_private(&root, &id)?;
    anyhow::ensure!(reopened.document() == session.document());
    let store = Store::open_private(root.clone(), id.0.clone()).await?;
    let png = imagine_server::workflow_image::encode(&image::DynamicImage::ImageRgb8(
        image::RgbImage::from_pixel(8, 8, image::Rgb([80, 120, 160])),
    ))?;
    let original = layout.tmp.join("own-procedural-original.png");
    root.write(original.strip_prefix(root.layout().root())?, &png)
        .map_err(anyhow::Error::msg)?;
    let asset = store.register_original("local", original.clone()).await?;
    let asset_id = asset["id"]
        .as_str()
        .ok_or_else(|| anyhow::anyhow!("own_asset_invalid"))?;
    anyhow::ensure!(store.read_asset(asset_id, "local").await? == png);
    anyhow::ensure!(std::fs::read_dir(&store.media)?.next().is_none());
    let destination = store
        .output_destination(Some(&id.0), false)
        .map_err(anyhow::Error::msg)?;
    let proof = destination.proof().map_err(anyhow::Error::msg)?;
    let mut pending = destination
        .reserve(&serde_json::json!(proof), png.len() as u64)
        .map_err(anyhow::Error::msg)?;
    let published = pending
        .publish_image(&png, "image", "image/png", None)
        .map_err(anyhow::Error::msg)?;
    anyhow::ensure!(published.path.parent() == Some(layout.images.as_path()));
    anyhow::ensure!(std::fs::read(&original)? == png);
    pending.commit();
    store.close().await?;
    println!(
        "{}",
        serde_json::json!({"passed":true,"synthetic_only":true,"gpu":false,
        "project":layout.root,"original":original,"published":published.path,"runtime":runtime,
        "mount":proof.config.mount,"source":proof.config.source,"filesystem":proof.config.filesystem,
        "first_byte_on_mounted_volume":true,"original_copied":false,"project_reopened":true})
    );
    Ok(())
}
